#define NDEBUG                      // так программу собирают для пользователей
#include <assert.h>
#include <stdio.h>
#include <string.h>

typedef struct {
    int items[8];
    int size;
} Stack;

static int stack_push(Stack *s, int value) {
    if (s->size == 8) {
        return 0;
    }
    s->items[s->size++] = value;
    return 1;
}

static int stack_pop(Stack *s, int *out) {
    if (s->size == 0) {
        return 0;
    }
    *out = s->items[--s->size];
    return 1;
}

int main(void) {
    Stack s = {{0}, 0};
    char command[16];
    while (scanf("%15s", command) == 1) {
        int value;
        if (strcmp(command, "push") == 0 && scanf("%d", &value) == 1) {
            assert(stack_push(&s, value));      // «не может не получиться»
        } else if (strcmp(command, "pop") == 0) {
            if (stack_pop(&s, &value)) {
                printf("%d\n", value);
            } else {
                printf("пусто\n");
            }
        } else if (strcmp(command, "size") == 0) {
            printf("%d\n", s.size);
        }
    }
    return 0;
}

