    int day;
    while (scanf("%d", &day) == 1) {
        if (day < 0 || day >= DAY_COUNT) {
            printf("%d: нет такого дня\n", day);
            continue;
        }
        printf("%d: %s, %s\n", day, DAY_NAMES[day], day >= SAT ? "выходной" : "рабочий");
    }
    return 0;
}

