additionalExercises.referenceSolution:
#include <assert.h>
#include <stdio.h>
#include <string.h>

static int heap[100];
static int heap_size;

static int heap_check(const int *a, int n, int *bad) {
    for (int i = 1; i < n; i++) {
        if (a[(i - 1) / 2] < a[i]) {
            *bad = i;
            return 0;
        }
    }
    return 1;
}

static void swap(int *x, int *y) {
    int t = *x;
    *x = *y;
    *y = t;
}

static void print_heap(void) {
    for (int i = 0; i < heap_size; i++) {
        printf(i + 1 < heap_size ? "%d " : "%d", heap[i]);
    }
    printf("\n");
}

static void push(int value) {
    int i = heap_size++;
    heap[i] = value;
    while (i > 0 && heap[(i - 1) / 2] < heap[i]) {
        swap(&heap[(i - 1) / 2], &heap[i]);
        i = (i - 1) / 2;
    }
    int bad;
    assert(heap_check(heap, heap_size, &bad));
    (void)bad;
}

static int pop(int *out) {
    if (heap_size == 0) {
        return 0;
    }
    *out = heap[0];
    heap[0] = heap[--heap_size];
    int i = 0;
    for (;;) {
        int largest = i;
        int left = 2 * i + 1, right = 2 * i + 2;
        if (left < heap_size && heap[left] > heap[largest]) {
            largest = left;
        }
        if (right < heap_size && heap[right] > heap[largest]) {
            largest = right;
        }
        if (largest == i) {
            break;
        }
        swap(&heap[i], &heap[largest]);
        i = largest;
    }
    int bad;
    assert(heap_check(heap, heap_size, &bad));
    (void)bad;
    return 1;
}

int main(void) {
    char command[16];
    while (scanf("%15s", command) == 1) {
        if (strcmp(command, "check") == 0) {
            int n, a[100];
            if (scanf("%d", &n) != 1 || n < 0 || n > 100) {
                break;
            }
            for (int i = 0; i < n; i++) {
                if (scanf("%d", &a[i]) != 1) {
                    return 0;
                }
            }
            int bad = 0;
            if (heap_check(a, n, &bad)) {
                printf("куча\n");
            } else {
                printf("нарушение: позиция %d, родитель %d\n", bad, (bad - 1) / 2);
            }
        } else if (strcmp(command, "push") == 0) {
            int value;
            if (scanf("%d", &value) != 1 || heap_size == 100) {
                break;
            }
            push(value);
            print_heap();
        } else if (strcmp(command, "pop") == 0) {
            int value;
            if (pop(&value)) {
                printf("%d\n", value);
            } else {
                printf("пусто\n");
            }
        }
    }
    return 0;
}

